-- Generated by tools/generate-database.py; fictional data only.

PRAGMA foreign_keys = ON;

CREATE TABLE VD_SCHEMA_VERSION (
    VERSION_NO INTEGER PRIMARY KEY
);

CREATE TABLE VD_COUNTER (
    KEY_NAME TEXT PRIMARY KEY,
    NEXT_VAL INTEGER NOT NULL
);

CREATE TABLE VD_SITE (
    ID TEXT PRIMARY KEY,
    NAME TEXT NOT NULL,
    SORT_ORDER INTEGER NOT NULL UNIQUE,
    LATE_RESTRICTED INTEGER NOT NULL,
    RETURN_LOAD_BY TEXT
);

CREATE TABLE VD_STATION (
    ID TEXT PRIMARY KEY,
    BRANCH_ID TEXT NOT NULL REFERENCES VD_SITE(ID),
    NAME TEXT NOT NULL,
    SORT_ORDER INTEGER NOT NULL,
    UNIQUE (ID, BRANCH_ID),
    UNIQUE (BRANCH_ID, SORT_ORDER)
);

CREATE TABLE VD_BUILDING (
    ID TEXT PRIMARY KEY,
    SITE_ID TEXT NOT NULL REFERENCES VD_SITE(ID),
    STATION_ID TEXT,
    NAME TEXT NOT NULL,
    FOREIGN KEY (STATION_ID, SITE_ID) REFERENCES VD_STATION(ID, BRANCH_ID)
);

CREATE TABLE VD_VEHICLE (
    ID TEXT PRIMARY KEY,
    NAME TEXT NOT NULL,
    POOL TEXT NOT NULL,
    SIZE_CLASS TEXT,
    HOME_SITE TEXT REFERENCES VD_SITE(ID),
    CURRENT_SITE TEXT REFERENCES VD_SITE(ID),
    LENGTH_CM NUMERIC NOT NULL,
    WIDTH_CM NUMERIC NOT NULL,
    HEIGHT_CM NUMERIC NOT NULL,
    VOLUME NUMERIC NOT NULL,
    WEIGHT_LIMIT NUMERIC NOT NULL,
    SEATS INTEGER NOT NULL,
    SORT_ORDER INTEGER NOT NULL,
    CHECK (POOL IN ('LOGI','BIZ'))
);

CREATE TABLE VD_DRIVER (
    ID TEXT PRIMARY KEY,
    NAME TEXT NOT NULL,
    POOL TEXT NOT NULL,
    HOME_SITE TEXT REFERENCES VD_SITE(ID),
    CURRENT_SITE TEXT REFERENCES VD_SITE(ID),
    SORT_ORDER INTEGER NOT NULL
);

CREATE TABLE VD_CARGO_CATEGORY (
    CODE TEXT PRIMARY KEY,
    NAME TEXT NOT NULL,
    FACTOR NUMERIC NOT NULL CHECK (FACTOR > 0),
    ACTIVE INTEGER NOT NULL CHECK (ACTIVE IN (0,1)),
    SORT_ORDER INTEGER NOT NULL
);

CREATE TABLE VD_CONFIG (
    KEY_NAME TEXT PRIMARY KEY,
    NUM_VALUE NUMERIC NOT NULL
);

CREATE TABLE VD_REG_SHIFT (
    ID TEXT PRIMARY KEY,
    BRANCH_ID TEXT NOT NULL REFERENCES VD_SITE(ID),
    LABEL TEXT NOT NULL,
    DEPART_MINUTE INTEGER NOT NULL CHECK (DEPART_MINUTE BETWEEN 0 AND 1439),
    SORT_ORDER INTEGER NOT NULL,
    VEHICLE_ID TEXT NOT NULL REFERENCES VD_VEHICLE(ID),
    DRIVER_ID TEXT NOT NULL REFERENCES VD_DRIVER(ID),
    UNIQUE (ID, BRANCH_ID),
    UNIQUE (BRANCH_ID, DEPART_MINUTE)
);

CREATE TABLE VD_REG_TRIP (
    SERVICE_DATE TEXT NOT NULL,
    SHIFT_ID TEXT NOT NULL REFERENCES VD_REG_SHIFT(ID),
    VEHICLE_ID TEXT NOT NULL REFERENCES VD_VEHICLE(ID),
    DRIVER_ID TEXT NOT NULL REFERENCES VD_DRIVER(ID),
    PRIMARY KEY (SERVICE_DATE, SHIFT_ID)
);

CREATE TABLE VD_REG_APP (
    ID INTEGER PRIMARY KEY,
    APP_NO TEXT NOT NULL UNIQUE,
    SUBMIT_SEQ INTEGER NOT NULL UNIQUE,
    APPLICANT TEXT NOT NULL,
    BRANCH_ID TEXT NOT NULL REFERENCES VD_SITE(ID),
    PICK_STATION_ID TEXT NOT NULL,
    DROP_STATION_ID TEXT NOT NULL,
    PICK_BUILDING TEXT,
    DROP_BUILDING TEXT,
    RECV_MODE TEXT NOT NULL,
    SERVICE_DATE TEXT NOT NULL,
    EXPECTED_MINUTE INTEGER,
    LOAD_MIN INTEGER NOT NULL CHECK (LOAD_MIN >= 0),
    UNLOAD_MIN INTEGER NOT NULL CHECK (UNLOAD_MIN >= 0),
    RECIPIENT_UNIT TEXT,
    RECIPIENT_NAME TEXT,
    RECIPIENT_PHONE TEXT,
    AGENT_NAME TEXT,
    AGENT_PHONE TEXT,
    STATUS TEXT NOT NULL,
    SHIFT_ID TEXT,
    ARRIVAL_MINUTE INTEGER,
    EXPECT_DIFF_MIN INTEGER,
    NOTE TEXT,
    FAILURE_REASON TEXT,
    INCIDENT TEXT,
    CREATED_AT TEXT NOT NULL,
    DELIVERED_AT TEXT,
    DELIVERED_BY TEXT,
    MATCH_ATTEMPT INTEGER NOT NULL,
    CHECK (RECV_MODE IN ('asap','exact')),
    CHECK (STATUS IN ('submitted','matched','unscheduled','delivered')),
    CHECK (EXPECTED_MINUTE IS NULL OR EXPECTED_MINUTE BETWEEN 0 AND 1439),
    FOREIGN KEY (PICK_STATION_ID, BRANCH_ID) REFERENCES VD_STATION(ID, BRANCH_ID),
    FOREIGN KEY (DROP_STATION_ID, BRANCH_ID) REFERENCES VD_STATION(ID, BRANCH_ID),
    FOREIGN KEY (SHIFT_ID, BRANCH_ID) REFERENCES VD_REG_SHIFT(ID, BRANCH_ID),
    FOREIGN KEY (SERVICE_DATE, SHIFT_ID) REFERENCES VD_REG_TRIP(SERVICE_DATE, SHIFT_ID),
    CHECK ((STATUS IN ('matched','delivered') AND SHIFT_ID IS NOT NULL) OR (STATUS IN ('submitted','unscheduled') AND SHIFT_ID IS NULL))
);

CREATE TABLE VD_REG_ITEM (
    APPLICATION_ID INTEGER NOT NULL REFERENCES VD_REG_APP(ID),
    LINE_NO INTEGER NOT NULL,
    NAME TEXT NOT NULL,
    LENGTH_CM NUMERIC NOT NULL CHECK (LENGTH_CM > 0),
    WIDTH_CM NUMERIC NOT NULL CHECK (WIDTH_CM > 0),
    HEIGHT_CM NUMERIC NOT NULL CHECK (HEIGHT_CM > 0),
    CATEGORY TEXT NOT NULL,
    QTY INTEGER NOT NULL CHECK (QTY > 0),
    WEIGHT NUMERIC NOT NULL CHECK (WEIGHT >= 0),
    PRIMARY KEY (APPLICATION_ID, LINE_NO)
);

CREATE TABLE VD_REG_MATCH_STEP (
    APPLICATION_ID INTEGER NOT NULL REFERENCES VD_REG_APP(ID),
    ATTEMPT INTEGER NOT NULL,
    STEP_NO INTEGER NOT NULL,
    CODE TEXT NOT NULL,
    MESSAGE TEXT NOT NULL,
    PRIMARY KEY (APPLICATION_ID, ATTEMPT, STEP_NO)
);

CREATE TABLE VD_MAINTENANCE (
    ID INTEGER PRIMARY KEY,
    VEHICLE_ID TEXT NOT NULL REFERENCES VD_VEHICLE(ID),
    FROM_DATE TEXT NOT NULL,
    TO_DATE TEXT NOT NULL,
    REASON TEXT,
    CHECK (FROM_DATE <= TO_DATE)
);

CREATE TABLE VD_DRIVER_LEAVE (
    ID INTEGER PRIMARY KEY,
    DRIVER_ID TEXT NOT NULL REFERENCES VD_DRIVER(ID),
    LEAVE_DATE TEXT NOT NULL,
    FROM_MINUTE INTEGER NOT NULL,
    TO_MINUTE INTEGER NOT NULL,
    LEAVE_TYPE TEXT,
    CHECK (FROM_MINUTE < TO_MINUTE)
);

CREATE TABLE VD_REST_HOUSE (
