    KIND TEXT NOT NULL,
    COST_MIN INTEGER NOT NULL
);

CREATE TABLE VD_MIN_TRIP_DAYS (
    SIZE_CLASS TEXT NOT NULL,
    SITE_ID TEXT NOT NULL REFERENCES VD_SITE(ID),
    DAYS INTEGER NOT NULL,
    PRIMARY KEY (SIZE_CLASS, SITE_ID)
);

CREATE TABLE VD_BIZ_PLACE (
    NAME TEXT PRIMARY KEY,
    SITE_ID TEXT REFERENCES VD_SITE(ID),
    IS_TRANSFER INTEGER NOT NULL
);

CREATE TABLE VD_BIZ_TRAVEL (
